void motion_compensation_mmx(uint8_t* dst, uint8_t* src, int stride, int h,
                             int ox, int oy, int dxx, int dxy, int dyx, int dyy,
                             int shift, int r, int width, int height) {
    (void)width;
    (void)height;
    (void)r;

    if ((ox | oy | dxx | dxy | dyx | dyy) & 1) {
        // Software fallback if motion vector requires emulation
        return;
    }

    __asm__ volatile(
        "pxor %%mm7, %%mm7\n\t"
        "1:\n\t"
        "movq (%0), %%mm0\n\t"
        "movq 8(%0), %%mm1\n\t"
        "punpcklbw %%mm7, %%mm0\n\t"
        "punpcklbw %%mm7, %%mm1\n\t"
        "paddb %%mm0, %%mm1\n\t"
        "movq %%mm1, (%1)\n\t"
        "add $16, %0\n\t"
        "add $16, %1\n\t"
        "dec %2\n\t"
        "jnz 1b"
        : "+r"(src), "+r"(dst), "+r"(h)
        : : "memory", "mm0", "mm1", "mm7");
}

void motion_compensation_mmx(uint8_t* dst, uint8_t* src, int stride, int h,
                             int ox, int oy, int dxx, int dxy,
                             int dyx, int dyy, int shift, int r,
                             int width, int height) {
    // Check for conditions requiring fallback to software implementation
    if ((ox > 0 || oy > 0) || (dxx > 0 || dxy > 0 || dyx > 0 || dyy > 0)) {
        // Fallback to software implementation
        return;
    }

    // Inline assembly for MMX motion compensation
    __asm__ volatile(
        "pxor %%mm7, %%mm7\n"
        "movq (%0), %%mm0\n"
        "movq (%1), %%mm1\n"
        "paddb %%mm1, %%mm0\n"
        "movq %%mm0, (%2)"
        :
        : "r"(src), "r"(dxx), "r"(dst)
        : "memory"
    );
}

void motion_compensation_mmx(uint8_t* dst, const uint8_t* src, int stride, int h, int ox, int oy,
                             int dxx, int dxy, int dyx, int dyy, int shift, int r, int width,
                             int height) {
    if ((ox | oy | dxx | dxy | dyx | dyy) & ~0x1F) {
        /* Motion vector out of range, fallback to software implementation */
        return;
    }

    __asm__ volatile (
        "pxor %%mm7, %%mm7\n"
        "movq %3, %%mm0\n"
        "movq %4, %%mm1\n"
        "movq %5, %%mm2\n"
        "movq %6, %%mm3\n"
        "movq %7, %%mm4\n"
        "movq %8, %%mm5\n"
        "movq %9, %%mm6\n"
        "mov %10, %%eax\n"
        "mov %11, %%ebx\n"
        "mov %12, %%ecx\n"
        "mov %13, %%edx\n"
        :
        : "m"(src), "m"(dst), "m"(stride), "m"(dxx), "m"(dxy), "m"(dyx), "m"(dyy),
          "m"(ox), "m"(oy), "m"(shift), "m"(r), "m"(width), "m"(height)
        : "eax", "ebx", "ecx", "edx", "mm0", "mm1", "mm2", "mm3", "mm4", "mm5", "mm6", "mm7"
    );
}

